    const key = `objects/${id}${ext ? `.${ext}` : ''}`;
    const mimeType = validMime(file.type);
    owned.push(key); // A failed put may have left a partial object.
    await disk.putStream(key, Readable.fromWeb(file.stream()), { contentType: mimeType, contentLength: file.size });
    const metadata = await disk.getMetaData(key);
    if (!Number.isSafeInteger(metadata.contentLength) ||
        metadata.contentLength < 0 ||
        metadata.contentLength !== file.size)
        throw new FileRepositoryError('INVALID_FILE_METADATA', 'Stored file size does not match the uploaded file.');
    const now = new Date().toISOString();
    const definition = await this.database
        .connection(options.connection)
        .collections.get(collection);
    const timestamp = (name) => definition?.fields?.find((field) => field.name === name)?.type ===
        'datetime'
        ? now.slice(0, -1)
        : now;
