        id,
        disk: options.disk,
        key,
        filename,
        ext,
        mimeType: validMime(metadata.contentType ?? mimeType),
        size: metadata.contentLength,
        createdAt: timestamp('createdAt'),
        updatedAt: timestamp('updatedAt'),
